<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {api} from '../api'
import {customerMoney} from '../customerPrices'
const props=defineProps<{revision:number;can:(permission:string)=>boolean}>(),emit=defineEmits<{navigate:[page:string]}>()
interface DashboardStats {orders?:number;ongoing?:number;pending?:number;receivable_cents?:number;unpaid_wage_cents?:number;warehouses?:number}
const month=ref(new Date().toLocaleDateString('sv-SE').slice(0,7)),stats=ref<DashboardStats>({}),error=ref(''),loading=ref(false),updated=ref('')
let generation=0
const metrics=[{key:'orders',label:'本月施工单',icon:'单',tone:'blue',hint:'所选月份全部施工单'},{key:'receivable_cents',label:'工地尚未核销',icon:'款',tone:'amber',hint:'所选月份施工的核销口径；公司实际待收见收款管理'},{key:'unpaid_wage_cents',label:'累计待发工资',icon:'薪',tone:'purple',hint:'所有日期累计；工资明细以工资管理为准'},{key:'warehouses',label:'启用仓库',icon:'仓',tone:'green',hint:'当前可使用的仓库'}] satisfies Array<{key:keyof DashboardStats;label:string;icon:string;tone:string;hint:string}>
const visibleMetrics=computed(()=>metrics.filter(metric=>stats.value[metric.key]!==undefined&&(metric.key!=='receivable_cents'||props.can('finance')&&props.can('customer_prices'))&&(metric.key!=='unpaid_wage_cents'||props.can('wages'))))
const stages=computed(()=>[{label:'进行中',count:Number(stats.value.ongoing||0),color:'#3978e8'},{label:'待交单',count:Number(stats.value.pending||0),color:'#e9a23b'},{label:'其他状态',count:Math.max(0,Number(stats.value.orders||0)-Number(stats.value.ongoing||0)-Number(stats.value.pending||0)),color:'#a2b4ce'}])
const actions=[{name:'施工制单',page:'orders',permission:'orders'},{name:'收款 / 欠款',page:'finance',permission:'finance'},{name:'查看库存',page:'inventory',permission:'warehouse'},{name:'工资管理',page:'wages',permission:'wages'}]
async function load(){const current=++generation;loading.value=true;error.value='';stats.value={};updated.value='';try{const result=await api<DashboardStats>('/dashboard?month='+month.value);if(current!==generation)return;stats.value=result;updated.value=new Date().toLocaleTimeString('zh-CN')}catch(e){if(current===generation)error.value=(e as Error).message}finally{if(current===generation)loading.value=false}}
watch(()=>[props.revision,props.can('customer_prices'),props.can('finance'),props.can('wages'),props.can('orders'),props.can('warehouse')],load);void load()
const timer=setInterval(()=>{if(typeof document==='undefined'||!document.hidden)void load()},60000)
onBeforeUnmount(()=>{clearInterval(timer);generation++})
</script>
<template><section class="overview" :aria-busy="loading">
 <header class="overview-head"><div><span class="eyebrow">特固施工 · 业务概览</span><h2>工作有序，账目清晰</h2><p>施工进度、待收款项和仓库情况，一处查看。</p></div><div class="overview-controls"><label>统计月份<input type="month" v-model="month" @change="load"></label><button :disabled="loading" @click="load">{{loading?'更新中…':'刷新数据'}}</button></div></header>
 <p class="update-status">● {{error?'更新失败，请重试读取最新数据':loading?'正在读取最新数据':updated?'已更新 '+updated+' · 每分钟自动刷新':'等待加载'}}</p><p v-if="error" class="error" role="alert">{{error}}</p>
 <div class="overview-metrics"><article v-for="m in visibleMetrics" :key="m.key" class="metric" :class="m.tone"><div class="metric-top"><span>{{m.label}}</span><span class="metric-icon" aria-hidden="true">{{m.icon}}</span></div><strong>{{m.key.endsWith('_cents')?customerMoney(stats[m.key],m.key==='unpaid_wage_cents'?can('wages'):can('finance')&&can('customer_prices')):Number(stats[m.key]).toLocaleString('zh-CN')}}</strong><p>{{m.hint}}</p></article></div>
 <div class="overview-bottom"><section v-if="stats.orders!==undefined" class="progress-panel"><div class="section-heading"><h3>施工单进度</h3><span>{{month}}</span></div><div v-if="Number(stats.orders)" class="progress-track" aria-label="施工单状态分布"><span v-for="s in stages" :key="s.label" :style="{width:s.count/Number(stats.orders)*100+'%',background:s.color}" :title="s.label+' '+s.count+'张'"></span></div><p v-else class="empty-state">本月还没有施工单，新增后将在这里汇总。</p><div class="progress-legend"><div v-for="s in stages" :key="s.label"><span><i :style="{background:s.color}"></i>{{s.label}}</span><strong>{{s.count}}<small> 张</small></strong></div></div><p class="footnote">其他状态包含已交单、已收款及已取消。</p></section><section class="next-panel"><span class="eyebrow">常用操作</span><h3>开始今天的工作</h3><p>按你的权限显示入口，随时继续处理业务。</p><div class="next-actions"><button v-for="a in actions.filter(x=>can(x.permission))" :key="a.page" @click="emit('navigate',a.page)">{{a.name}} <span>→</span></button><p v-if="!actions.some(x=>can(x.permission))">暂无业务入口，请联系管理员开通权限。</p></div></section></div>
</section></template>
<style scoped>
.overview{margin-bottom:24px}.overview-head{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:28px 30px;background:linear-gradient(115deg,#edf4ff,#f8fafc 65%,#eef7f3);border:1px solid #dce6f1;border-radius:18px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:1px;color:#58728f}.overview-head h2{font-size:26px;margin:10px 0;color:#203c59}.overview-head p,.next-panel p{color:#718094;font-size:13px;margin:0;line-height:1.7}.overview-controls{display:flex;align-items:flex-end;gap:10px}.overview-controls label{font-size:12px;color:#617084}.overview-controls input{margin-top:7px;background:white}.update-status{margin:14px 2px;font-size:12px;color:#698c81}.overview-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.metric{background:#fff;border:1px solid #e4eaf1;border-radius:14px;padding:20px;min-width:0;border-top:3px solid var(--accent);--accent:#3978e8;--tint:#eef4ff}.metric.amber{--accent:#c9902e;--tint:#fff7e9}.metric.purple{--accent:#8b6ad0;--tint:#f5f0fc}.metric.green{--accent:#29977d;--tint:#eaf8f2}.metric-top{display:flex;align-items:center;justify-content:space-between;gap:8px;color:#53677b;font-size:13px}.metric-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:var(--tint);color:var(--accent);font-weight:700}.metric>strong{display:block;font-size:clamp(22px,2.2vw,32px);letter-spacing:-.6px;color:#20364e;margin:13px 0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.metric p{margin:0;color:#8493a3;font-size:11px}.overview-bottom{display:grid;grid-template-columns:1.2fr 1fr;gap:16px;margin-top:18px}.progress-panel,.next-panel{padding:24px;background:white;border:1px solid #e4eaf1;border-radius:14px;min-width:0}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.section-heading h3,.next-panel h3{margin:0;font-size:16px;color:#31495e}.section-heading>span{color:#8493a3;font-size:12px}.progress-track{display:flex;height:12px;border-radius:6px;overflow:hidden;margin:27px 0 22px;background:#f2f4f8}.progress-legend{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.progress-legend span{font-size:12px;color:#738194;display:flex;align-items:center;gap:6px}.progress-legend i{width:7px;height:7px;border-radius:50%}.progress-legend strong{display:block;margin-top:10px;font-size:22px;color:#334b62}.progress-legend small{display:inline;font-size:11px;font-weight:400}.footnote{font-size:11px;color:#8493a3;margin:20px 0 0}.next-panel{background:#f8fbfe}.next-panel h3{margin:10px 0}.next-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:18px}.next-actions button{display:flex;justify-content:space-between;text-align:left;gap:12px;background:white;border-color:#dfe8f0;padding:11px 14px;font-size:13px}.next-actions button span{color:#6f94bd}.empty-state{color:#8c99a8;font-size:13px;padding:16px 0}@media(max-width:1000px){.overview-head{align-items:flex-start;flex-direction:column}.overview-bottom{grid-template-columns:1fr}.overview-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.overview-head{padding:20px}.overview-controls{flex-wrap:wrap}.overview-metrics,.next-actions{grid-template-columns:1fr}}
@media screen{
.overview-head{height:auto;padding:20px 22px;background:#f0f5fc;border-color:#dce6f2;border-radius:8px}
.eyebrow{letter-spacing:0;color:#436ba1}
.overview-head h2{font-size:21px;margin:5px 0;color:#263d56}
.overview-metrics{gap:12px}
.metric{border-radius:8px;padding:17px;border-top-width:2px}
.metric-icon{border-radius:6px}
.metric>strong{font-size:26px;letter-spacing:0;margin:10px 0}
.metric p{font-size:12px}
.overview-bottom{gap:12px;margin-top:12px}
.progress-panel,.next-panel{border-radius:8px;padding:18px}
.next-panel{background:#fff}
.next-actions button{min-height:40px}
}
@media screen and (max-width:540px){.overview-head{padding:16px}.overview-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.metric{padding:12px}.metric>strong{font-size:20px}.metric p{line-height:1.4}.progress-legend{gap:5px}.progress-legend strong{font-size:18px}}
</style>
